begin;
create function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'ASSERTION: %',label;end if;end$$;
do $$declare u uuid:=gen_random_uuid();r uuid:=gen_random_uuid();t uuid:=gen_random_uuid();o uuid:=gen_random_uuid();p uuid;d uuid;printers uuid[]:='{}';devices uuid[]:='{}';jobs uuid[]:='{}';claims jsonb[]:='{}';c jsonb;a uuid;before_hash text;after_hash text;i integer;slug text;
begin
 slug:='kp-rollback-'||r;insert into auth.users(id) values(u);insert into public.restaurants(id,name,slug) values(r,'Synthetic rollback',slug);insert into public.restaurant_staff(restaurant_id,user_id,role) values(r,u,'owner');insert into public.tables(id,restaurant_id,table_name,local_id,name,table_token) values(t,r,'Rollback 1','rollback-1','Rollback 1',gen_random_uuid()::text);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);perform public.set_kitchen_print_control(r,true,false);
 for i in 1..5 loop
  p:=gen_random_uuid();d:=gen_random_uuid();printers:=array_append(printers,p);devices:=array_append(devices,d);
  insert into public.kitchen_printers(id,restaurant_id,name,ip,updated_by) values(p,r,'Rollback printer '||i,'192.168.7.'||(50+i),u);
  insert into public.kitchen_print_devices(id,restaurant_id,operator_id,device_name,secret_hash,last_heartbeat) values(d,r,u,'Synthetic stopped agent '||i,encode(extensions.digest(repeat('f',64),'sha256'),'hex'),clock_timestamp());insert into public.kitchen_print_device_printers values(r,d,p);
  jobs:=array_append(jobs,public.request_kitchen_test_print(p,gen_random_uuid()));
  if i>1 then c:=public.claim_kitchen_printer_job(d,repeat('f',64));claims:=array_append(claims,c);if i>2 then a:=gen_random_uuid();perform public.begin_kitchen_print_attempt(d,repeat('f',64),(c->>'jobId')::uuid,(c->>'claimToken')::uuid,a,(c->>'configRevision')::bigint);if i=4 then perform public.finish_kitchen_print_attempt(d,repeat('f',64),(c->>'jobId')::uuid,(c->>'claimToken')::uuid,a,'transmitted',null);elsif i=5 then perform public.finish_kitchen_print_attempt(d,repeat('f',64),(c->>'jobId')::uuid,(c->>'claimToken')::uuid,a,'uncertain','TRANSPORT_FAILED');end if;end if;end if;
 end loop;
 select string_agg(snapshot_hash,',' order by id) into before_hash from public.kitchen_print_jobs where restaurant_id=r;
 perform public.set_kitchen_print_control(r,false,false);for i in 1..5 loop perform public.revoke_kitchen_print_device(devices[i],'Synthetic rollback: old agent stopped');end loop;
 begin perform public.claim_kitchen_printer_job(devices[1],repeat('f',64));raise exception 'REVOKED_CLAIM_ALLOWED';exception when insufficient_privilege then null;end;
 c:=claims[1];begin perform public.begin_kitchen_print_attempt(devices[2],repeat('f',64),jobs[2],(c->>'claimToken')::uuid,gen_random_uuid(),(c->>'configRevision')::bigint);raise exception 'REVOKED_BEGIN_ALLOWED';exception when insufficient_privilege then null;end;
 begin perform public.claim_kitchen_print_job(slug);raise exception 'LEGACY_REOPENED';exception when others then if sqlerrm<>'PRINT_PROTOCOL_UPGRADE_REQUIRED' then raise;end if;end;
 perform pg_temp.assert_true((select not enabled and protocol_version=2 from public.kitchen_print_controls where restaurant_id=r),'disabled keeps sticky v2');
 update public.kitchen_print_jobs set lease_expires_at=clock_timestamp()-interval '1 second' where id in(jobs[2],jobs[3]);perform public.list_kitchen_printers(r);
 perform pg_temp.assert_true((select state='queued' from public.kitchen_print_jobs where id=jobs[1]),'queued work retained');perform pg_temp.assert_true((select state='retry_wait' from public.kitchen_print_jobs where id=jobs[2]),'unconsumed lease retained safely');perform pg_temp.assert_true((select state='uncertain' from public.kitchen_print_jobs where id=jobs[3]),'dispatch expiry quarantined');perform pg_temp.assert_true((select state='transmitted' from public.kitchen_print_jobs where id=jobs[4]),'transmitted evidence retained');perform pg_temp.assert_true((select state='uncertain' from public.kitchen_print_jobs where id=jobs[5]),'existing uncertainty retained');
 perform public.disable_kitchen_printer(printers[3],'Rollback keeps delivery warning visible');perform public.resolve_kitchen_print_uncertainty(jobs[3],'no_paper_agent_stopped','Only synthetic fixture; old agent stopped and inspected',true);perform pg_temp.assert_true((select state='uncertain' from public.kitchen_print_jobs where id=jobs[5]),'no bulk uncertainty resolution');
 insert into public.orders(id,restaurant_id,table_id,total,subtotal,created_at) values(o,r,t,10,10,clock_timestamp());insert into public.order_items(restaurant_id,order_id,item_name,name_snapshot,quantity,price) values(r,o,'Synthetic food after rollback','Synthetic food after rollback',1,10);set constraints all immediate;
 perform pg_temp.assert_true((select total=10 and paid_at is null and status<>'paid' from public.orders where id=o),'food order and pay-later state preserved after rollback');perform pg_temp.assert_true((select count(*)=5 from public.kitchen_print_jobs where restaurant_id=r),'no auto backlog or bulk cancellation');
 select string_agg(snapshot_hash,',' order by id) into after_hash from public.kitchen_print_jobs where restaurant_id=r;perform pg_temp.assert_true(before_hash=after_hash,'all immutable snapshots preserved');perform pg_temp.assert_true((select count(*)>=6 from public.kitchen_print_attempts where restaurant_id=r),'attempt evidence retained');
end$$;
rollback;
